css:
.dcx{ -webkit-text-size-adjust: 100%; }
.dcx{ margin: 0; background: #fff; color: #0B1512; font-family: 'Instrument Sans', system-ui, sans-serif; -webkit-font-smoothing: antialiased; overflow-x:clip; }
.dcx *{ box-sizing: border-box; }
.dcx h1,.dcx h2,.dcx h3,.dcx h4{ margin: 0; font-family: 'Source Serif 4', Georgia, serif; font-weight: 700; letter-spacing: -0.015em; }
.dcx p{ margin: 0; text-wrap: pretty; }
.dcx a{ color: #1DBF6B; text-decoration: none; }
.dcx a:hover{ color: #2FD97F; }
.dcx :focus-visible{ outline: 2px solid #2FD97F; outline-offset: 3px; border-radius: 4px; }
.dcx [data-burger]{ display: none; }
@media (max-width: 1100px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-burger]{ display: inline-flex !important; }
.dcx [data-hero],.dcx [data-conf],.dcx [data-cta]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-steps]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-ind]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-h1]{ font-size: 40px !important; }
.dcx [data-h2]{ font-size: 30px !important; }
.dcx [data-arrow],.dcx [data-cta-img]{ display: none !important; }
}
@media (max-width: 700px){.dcx [data-steps],.dcx [data-ind],.dcx [data-checks],.dcx [data-stats]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-h1]{ font-size: 32px !important; }
.dcx [data-pad]{ padding-left: 20px !important; padding-right: 20px !important; }
}
